{
  "contract": "BULLRUNNERSCLUB",
  "closure": {
    "site_function": "withdraw",
    "site_call": ".call",
    "functions": [
      "withdraw",
      "mint"
    ],
    "justification": "The 'withdraw' function can re-enter due to low-level value transfer. Both 'withdraw' and 'mint' modify '_ethBal' and 'team_balance', which are exposed during the call."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "withdraw",
      "mint"
    ],
    "nesting_bound": {
      "withdraw": 0,
      "mint": 1
    }
  },
  "phases": {
    "function": "withdraw",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before call",
      "to_marker": "after call"
    },
    "post": {
      "name": "post",
      "from_marker": "after call",
      "to_marker": "exit"
    },
    "linearization_point": "after call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint",
      "meaning": "The amount of balance mid-transfer during the callback window.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "team_balance == _ethBal + inFlight",
    "stable_formula": "team_balance == _ethBal",
    "kind": "additive"
  },
  "composition": {
    "target_property": "team_balance <= _ethBal",
    "rule": "exposure invariant implies property"
  }
}
